// kindsgen turns the core kind declarations into Go and TypeScript types. The
// declarations under kinds/ are the single source of truth for what a record
// is; every type representation of them is generated from those files, so the
// code and the contract cannot drift.
//
// It carries its OWN reader (internal/kinddialect, whose one dependency is
// yaml.v3) rather than reading through internal/vocabulary, so that a broken
// generated file can never take the loader's package graph — and with it the
// generator that would fix the file — out of the build. The two readers are
// held together by the conformance test in internal/corekinds, which is what
// makes a second reader affordable.
//
// Usage:
//
//	kindsgen [-kinds dir] [-go dir] [-ts file] [-lang all|go|ts]
//
// A declaration using a dialect feature the reader does not understand FAILS
// the run, naming the document and the key. Generating past one would emit a
// type that silently means something else, which is the one outcome a review of
// the generated file cannot catch.
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/geoah/substrate/internal/kinddialect"
)

func main() {
	kindsDir := flag.String("kinds", filepath.Join("kinds", "core.substrate.reamde.dev"),
		"the authority directory to read declarations from")
	goDir := flag.String("go", filepath.Join("internal", "corekinds"),
		"the directory the generated Go package is written to")
	tsFile := flag.String("ts", filepath.Join("web", "console", "src", "lib", "generated", "corekinds.ts"),
		"the file the generated TypeScript module is written to")
	lang := flag.String("lang", "all", "which half to generate: all, go or ts")
	flag.Parse()

	if err := run(*kindsDir, *goDir, *tsFile, *lang); err != nil {
		fmt.Fprintf(os.Stderr, "kindsgen: %v\n", err)
		os.Exit(1)
	}
}

func run(kindsDir, goDir, tsFile, lang string) error {
	if lang != "all" && lang != "go" && lang != "ts" {
		return fmt.Errorf("-lang is all, go or ts, not %q", lang)
	}
	// The header names the source as the tree spells it, never as this
	// invocation happened to spell it: `kinds:gen:check` renders into a
	// temporary directory, and a header that carried the output path would
	// report a difference on every run.
	authority := filepath.Base(filepath.Clean(kindsDir))
	source := "kinds/" + authority

	decls, err := kinddialect.ReadDir(kindsDir)
	if err != nil {
		return err
	}
	if len(decls) == 0 {
		return fmt.Errorf("%s declares no kinds", kindsDir)
	}
	p, err := buildPlan(authority, decls)
	if err != nil {
		return err
	}
	if lang == "all" || lang == "go" {
		files, err := generateGo(p, source)
		if err != nil {
			return err
		}
		if err := writeGo(goDir, files); err != nil {
			return err
		}
	}
	if lang == "all" || lang == "ts" {
		if err := writeFile(tsFile, generateTS(p, source)); err != nil {
			return err
		}
	}
	return nil
}

// generatedMark is how a file says it is this generator's to overwrite — and to
// DELETE: a kind that leaves the tree must take its generated file with it, or
// the package keeps compiling a type nothing declares.
const generatedMark = "// Code generated by cmd/kindsgen"

func writeGo(dir string, files map[string][]byte) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	for _, name := range sortedNames(files) {
		if err := writeFile(filepath.Join(dir, name), files[name]); err != nil {
			return err
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	for _, e := range entries {
		if e.IsDir() || files[e.Name()] != nil || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		path := filepath.Join(dir, e.Name())
		raw, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		if !strings.HasPrefix(string(raw), generatedMark) {
			continue // a hand-written file in the package (the conformance test)
		}
		if err := os.Remove(path); err != nil {
			return err
		}
		fmt.Fprintf(os.Stderr, "kindsgen: removed %s: nothing declares it any more\n", path)
	}
	return nil
}

// writeFile writes only a CHANGED file, so a run that changes nothing touches
// nothing: an unchanged mtime is what keeps the build cache and the editor from
// reacting to a no-op generation.
func writeFile(path string, content []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if old, err := os.ReadFile(path); err == nil && string(old) == string(content) {
		return nil
	}
	return os.WriteFile(path, content, 0o644)
}
